curl 'https://agent.example.com/a2a/message:send' \
  -H 'A2A-Version: 1.0' \
  -H 'A2A-Extensions: https://agent.example.com/extensions/harness-stream/v1' \
  -H 'Content-Type: application/a2a+json' \
  -H 'Accept: application/a2a+json' \
  --data '{
    "message": {
      "messageId": "input-1",
      "role": "ROLE_USER",
      "parts": [{"text": "读取 README，检查项目目录，并在后台运行测试。"}]
    },
    "configuration": {
      "returnImmediately": true,
      "historyLength": 0,
      "acceptedOutputModes": ["text/plain", "application/json"]
    }
  }'

const baseUrl = "https://agent.example.com/a2a";
const extension = "https://agent.example.com/extensions/harness-stream/v1";
const response = await fetch(`${baseUrl}/message:send`, {
  method: "POST",
  headers: {
    "A2A-Version": "1.0",
    "A2A-Extensions": extension,
    "Content-Type": "application/a2a+json",
    Accept: "application/a2a+json",
    // 按 AgentCard 和实际部署补充认证请求头。
  },
  body: JSON.stringify({
    message: {
      messageId: crypto.randomUUID(),
      role: "ROLE_USER",
      parts: [{ text: "读取 README，检查项目目录，并在后台运行测试。" }],
    },
    configuration: { returnImmediately: true, historyLength: 0 },
  }),
});
if (!response.ok) throw new Error(await response.text());
const activated = response.headers.get("A2A-Extensions") ?? "";
if (!activated.split(",").map(value => value.trim()).includes(extension)) {
  throw new Error("服务端未确认完整输出扩展。");
}
const { task } = await response.json();
const { eventsUrl, startAfterSeq } = task.metadata[extension];
const streamUrl = new URL(eventsUrl);
streamUrl.searchParams.set("afterSeq", String(startAfterSeq));
console.log({ taskId: task.id, streamUrl: streamUrl.href });
// 使用支持自定义请求头的 SSE 客户端订阅 streamUrl。
// 顺序应用 snapshot / event；持久化成功提交的 seq。

